    // Page header used by the Rainbow Pool and contributions pages: icon chip · title · (actions)
    function _dtiPageHead(h1, icon) {
        if (!h1 || h1.closest('.dti-ph')) return h1?.closest('.dti-ph');
        const head = document.createElement('div'); head.className = 'dti-ph';
        h1.before(head);
        head.innerHTML = `<span class="dti-ph-ico">${icon}</span>`;
        head.appendChild(h1);
        return head;
    }

